/**
 * IdentityCard — spec §10.1, §12
 *
 * Verified-identity card. Three variants:
 *  - rail:  shown in the right rail at lg+ (compact, sticky context)
 *  - page:  full-width on the Identity deep-link page (mobile parity)
 *  - share: print/share-sheet rendition (no interactive controls)
 */
import * as React from 'react';
import {
    Avatar,
    Box,
    Card,
    CardContent,
    Divider,
    Stack,
    Typography,
} from '@mui/material';
import AssignmentIndIcon from '@mui/icons-material/AssignmentInd';
import LocalLibraryIcon from '@mui/icons-material/LocalLibrary';
import SchoolIcon from '@mui/icons-material/School';
import QRCodeLib from 'react-qr-code';
import {
    elevation,
    iconSizes,
    radius,
    semanticColors,
} from '@/constants/ThemeConstants';

// react-qr-code default export shim (matches existing IdentityDisplay.tsx pattern).
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const QRCode: React.ComponentType<{ value: string; size?: number; viewBox?: string; style?: React.CSSProperties }> =
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (QRCodeLib as any).QRCode || (QRCodeLib as any);

export type IdentityCardVariant = 'rail' | 'page' | 'share';

export interface IdentityCardProps {
    variant?: IdentityCardVariant;
    /** Display name. */
    name: string;
    /** Profile id (also used as QR value + verification token). */
    profileId: string;
    /** Photo URL. Falls back to initials. */
    photoUrl?: string;
    profileType?: string;
    entryYear?: number;
    exitYear?: number;
    firstJnvName?: string;
    otherJnvNames?: string;
    /** Optional verification token to display below the QR. */
    verificationToken?: string;
    /** Slot for a primary action (e.g. Download button). Hidden in `share` variant. */
    action?: React.ReactNode;
    /** Public-facing URL for the profile. */
    siteUrl?: string;
}

const initialsOf = (name: string): string =>
    name
        .split(/\s+/)
        .filter(Boolean)
        .slice(0, 2)
        .map((p) => p[0]?.toUpperCase() ?? '')
        .join('');

export const IdentityCard: React.FC<IdentityCardProps> = ({
    variant = 'rail',
    name,
    profileId,
    photoUrl,
    profileType,
    entryYear,
    exitYear,
    firstJnvName,
    otherJnvNames,
    verificationToken,
    action,
    siteUrl = 'https://nvsalumni.in',
}) => {
    const isShare = variant === 'share';
    const qrSize = variant === 'rail' ? 96 : 128;
    const yearsLabel =
        entryYear === undefined && exitYear === undefined
            ? null
            : `${entryYear && entryYear !== 0 ? entryYear : 'Present'} – ${
                  exitYear && exitYear !== 0 ? exitYear : 'Present'
              }`;
    const schools = [firstJnvName, otherJnvNames].filter(Boolean).join(', ');

    return (
        <Card
            component="section"
            aria-label="Digital identity card"
            elevation={0}
            sx={{
                width: '100%',
                maxWidth: variant === 'rail' ? 380 : 480,
                borderRadius: `${radius.lg}px`,
                backgroundColor: semanticColors.surface.card,
                boxShadow: isShare ? 'none' : elevation[1],
                overflow: 'hidden',
            }}
        >
            <Box
                sx={{
                    backgroundColor: semanticColors.accent.identity,
                    display: 'flex',
                    justifyContent: 'center',
                    py: 3,
                }}
            >
                <Avatar
                    src={photoUrl}
                    alt={photoUrl ? `${name} profile photo` : `${name} initials`}
                    sx={{
                        width: variant === 'rail' ? 120 : 160,
                        height: variant === 'rail' ? 120 : 160,
                        bgcolor: semanticColors.surface.card,
                        color: semanticColors.text.primary,
                        fontSize: '2rem',
                    }}
                >
                    {!photoUrl && initialsOf(name)}
                </Avatar>
            </Box>
            <Divider />
            <CardContent>
                <Stack spacing={0.5} sx={{ mb: 2 }}>
                    <Typography
                        variant="h5"
                        component="h2"
                        sx={{ color: semanticColors.text.primary, fontWeight: 600 }}
                    >
                        {name || '[ Upload photo ]'}
                    </Typography>
                    <Typography variant="caption" sx={{ color: semanticColors.text.secondary }}>
                        {siteUrl}
                    </Typography>
                    <Typography
                        variant="caption"
                        sx={{
                            color: semanticColors.text.secondary,
                            fontFamily: 'monospace',
                        }}
                    >
                        {profileId}
                    </Typography>
                </Stack>
                <Stack direction="row" spacing={2} sx={{ alignItems: 'flex-start' }}>
                    <Box sx={{ flexShrink: 0 }}>
                        <QRCode
                            value={profileId}
                            size={qrSize}
                            viewBox="0 0 100 100"
                            style={{ height: 'auto', maxWidth: qrSize, width: qrSize }}
                        />
                    </Box>
                    <Stack spacing={0.75} sx={{ minWidth: 0, flex: 1 }}>
                        {profileType && (
                            <MetaRow icon={<AssignmentIndIcon sx={{ fontSize: iconSizes.metaIcon }} />}>
                                {profileType}
                            </MetaRow>
                        )}
                        {yearsLabel && (
                            <MetaRow icon={<LocalLibraryIcon sx={{ fontSize: iconSizes.metaIcon }} />}>
                                {yearsLabel}
                            </MetaRow>
                        )}
                        {schools && (
                            <MetaRow icon={<SchoolIcon sx={{ fontSize: iconSizes.metaIcon }} />}>
                                {schools}
                            </MetaRow>
                        )}
                    </Stack>
                </Stack>
                {verificationToken && (
                    <Typography
                        variant="body2"
                        sx={{
                            mt: 1.5,
                            color: semanticColors.text.secondary,
                            fontVariantNumeric: 'tabular-nums',
                            fontFamily: 'monospace',
                        }}
                    >
                        {verificationToken}
                    </Typography>
                )}
                {!isShare && action && <Box sx={{ mt: 2 }}>{action}</Box>}
            </CardContent>
        </Card>
    );
};

const MetaRow: React.FC<{ icon: React.ReactNode; children: React.ReactNode }> = ({
    icon,
    children,
}) => (
    <Stack
        direction="row"
        spacing={1}
        sx={{
            alignItems: 'center',
            color: semanticColors.text.secondary,
            fontSize: '0.875rem',
            lineHeight: 1.4,
        }}
    >
        <Box aria-hidden="true" sx={{ display: 'inline-flex', color: semanticColors.text.muted }}>
            {icon}
        </Box>
        <Box sx={{ minWidth: 0, overflowWrap: 'anywhere' }}>{children}</Box>
    </Stack>
);

export default IdentityCard;
