/**
 * DetailRow — shared label/value row used inside dialogs and info panels.
 *
 * Keeps icon sizing, label/value typography and spacing identical wherever
 * member or attendee details are displayed. Previously each dialog rolled its
 * own variant (caption vs body2 labels, body1 500-weight vs body2 values),
 * which made otherwise-similar dialogs look inconsistent.
 */
import * as React from 'react';
import { Box, Typography } from '@mui/material';

export interface DetailRowProps {
    icon: React.ReactNode;
    label: string;
    value: React.ReactNode;
    /** Optional tint for the value text (e.g. 'success.main' for a status). */
    valueColor?: string;
}

export const DetailRow: React.FC<DetailRowProps> = ({ icon, label, value, valueColor }) => (
    <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1, py: 0.5 }}>
        <Box
            sx={{
                color: 'action.active',
                display: 'flex',
                flexShrink: 0,
                mt: '2px',
                '& > svg': { fontSize: '1rem' },
            }}
        >
            {icon}
        </Box>
        <Box sx={{ minWidth: 0, flexGrow: 1 }}>
            <Typography variant="caption" color="text.secondary" sx={{ display: 'block', lineHeight: 1.2 }}>
                {label}
            </Typography>
            <Typography
                variant="body2"
                component="div"
                sx={{ wordBreak: 'break-word', color: valueColor }}
            >
                {value || '—'}
            </Typography>
        </Box>
    </Box>
);

export default DetailRow;
